window.AI9_DATA = window.AI9_DATA || {};
window.AI9_DATA.flashcards = [
  { id: "r1", deck: "Responsible AI", tag: "Fairness", front: "Fairness principle", back: "<p><strong>Fairness</strong> means an AI system treats all groups of people equitably and does not advantage or disadvantage any demographic group.</p><p class=\"faint\">Do not confuse with inclusiveness \u2014 fairness is about how the system <em>treats</em> people; inclusiveness is about whether everyone can <em>use</em> it. Giveaway words: bias, demographic, disadvantaged, equitably.</p>" },
  { id: "r2", deck: "Responsible AI", tag: "Reliability", front: "Reliability and safety principle", back: "<p><strong>Reliability and safety</strong> means an AI system must perform consistently under expected conditions and fail safely when it encounters unexpected ones.</p><p class=\"faint\">Giveaway words: fail safe, rigorous testing, harm, unexpected conditions. Do not confuse with accountability \u2014 reliability is about consistent <em>behavior</em>; accountability is about who <em>answers</em> for outcomes.</p>" },
  { id: "r3", deck: "Responsible AI", tag: "Privacy", front: "Privacy and security principle", back: "<p><strong>Privacy and security</strong> means personal data must be collected, stored, and used with consent, appropriate protections, and in compliance with regulations.</p><p class=\"faint\">Giveaway words: consent, personal data, encryption, retention. Do not confuse with transparency \u2014 privacy is about protecting data; transparency is about explaining how the system works.</p>" },
  { id: "r4", deck: "Responsible AI", tag: "Inclusiveness", front: "Inclusiveness principle", back: "<p><strong>Inclusiveness</strong> means AI systems must be accessible to everyone regardless of ability, background, or disability, so nobody is excluded from the benefits of AI.</p><p class=\"faint\">Giveaway words: accessible, everyone, regardless of ability, disability. Do not confuse with fairness \u2014 inclusiveness is about whether everyone can <em>use</em> the system; fairness is about whether it <em>treats</em> all groups equally.</p>" },
  { id: "r5", deck: "Responsible AI", tag: "Transparency", front: "Transparency principle", back: "<p><strong>Transparency</strong> means people should be able to understand how an AI system makes decisions, what data it uses, and what its limitations are.</p><p class=\"faint\">Giveaway words: explain, understand, interpretability, disclose. Do not confuse with accountability \u2014 transparency is about <em>understanding</em> the system; accountability is about <em>answering for</em> its outcomes.</p>" },
  { id: "r6", deck: "Responsible AI", tag: "Accountability", front: "Accountability principle", back: "<p><strong>Accountability</strong> means people and organizations must be answerable for AI systems they build and deploy, with appropriate governance frameworks in place.</p><p class=\"faint\">Giveaway words: governance, responsible for, oversight, framework. Do not confuse with transparency \u2014 accountability is about <em>who answers</em> for outcomes; transparency is about <em>how to understand</em> the system.</p>" },
  { id: "r7", deck: "Responsible AI", tag: "Fairness", front: "Fairness scenario: loan application model", back: "<p>If a loan model approves applications at a higher rate for one demographic group than another with similar credit profiles, the <strong>fairness</strong> principle is being violated.</p><p class=\"faint\">Exam trap: the fix \u2014 auditing predictions across groups, rebalancing training data \u2014 is a fairness mitigation, not a privacy or reliability one. Keep the principles distinct.</p>" },
  { id: "r8", deck: "Responsible AI", tag: "Transparency", front: "Transparency vs accountability \u2014 key contrast", back: "<p><strong>Transparency</strong> focuses on making system behavior explainable and understandable to users and stakeholders; <strong>accountability</strong> focuses on ensuring that a person or organization is responsible and answerable for the system\u2019s decisions and outcomes.</p><p class=\"faint\">Exam trap: a question about \u201cwho is responsible if the model causes harm\u201d targets accountability, not transparency. A question about \u201ccommunicating how the model reached a result\u201d targets transparency.</p>" },
  { id: "r9", deck: "Responsible AI", tag: "Inclusiveness", front: "Inclusiveness vs fairness \u2014 key contrast", back: "<p><strong>Inclusiveness</strong> asks whether all users can access and use the system (e.g., screen-reader support, multiple languages); <strong>fairness</strong> asks whether the system produces equitable outcomes across different demographic groups.</p><p class=\"faint\">Exam trap: \u201cthe app has no audio mode for visually impaired users\u201d is an inclusiveness issue, not a fairness issue, even though both involve groups of people.</p>" },
  { id: "r10", deck: "Responsible AI", tag: "Content Safety", front: "Azure AI Content Safety", back: "<p><strong>Azure AI Content Safety</strong> is a service that detects and filters harmful content in text and images, providing severity scores (0\u20136) for four harm categories: hate, sexual, violence, and self-harm.</p><p class=\"faint\">Do not confuse with prompt shields \u2014 Content Safety detects harmful <em>content</em>; prompt shields specifically detect jailbreak and indirect prompt injection <em>attacks</em>. Both are part of responsible AI mitigation.</p>" },
  { id: "r11", deck: "Responsible AI", tag: "Content Safety", front: "Four harm categories in Azure AI Content Safety", back: "<p>Azure AI Content Safety evaluates four categories: <strong>hate, sexual, violence, and self-harm</strong>. Each returns a severity score from 0 (safe) to 6 (high severity), and deployments can set thresholds per category.</p><p class=\"faint\">Exam trap: there are exactly four categories. Do not add \u201cfraud\u201d or \u201cspam\u201d \u2014 those are not Content Safety categories. Configurable thresholds mean you can be stricter for some categories than others.</p>" },
  { id: "r12", deck: "Responsible AI", tag: "Content Safety", front: "Severity thresholds in Azure AI Content Safety", back: "<p><strong>Severity thresholds</strong> are per-category configuration values that determine at what score (0\u20136) Content Safety blocks or flags content, allowing teams to tune strictness for their application\u2019s risk tolerance.</p><p class=\"faint\">Exam trap: thresholds are configurable \u2014 not fixed. A children\u2019s app sets a lower threshold (blocks at a lower score) than a medical platform. Lower threshold = stricter filtering.</p>" },
  { id: "r13", deck: "Responsible AI", tag: "Prompt Shields", front: "Prompt shields", back: "<p><strong>Prompt shields</strong> are a feature of Azure AI Content Safety that detects and blocks jailbreak attempts and indirect prompt injection attacks before they reach the model.</p><p class=\"faint\">Exam trap: prompt shields address <em>attack</em> techniques; content-category filters address harmful <em>content</em>. Both protect responsible AI deployments but they target different threat types.</p>" },
  { id: "r14", deck: "Responsible AI", tag: "Prompt Shields", front: "Jailbreak vs indirect prompt injection", back: "<p>A <strong>jailbreak</strong> is a direct user attempt to override a model\u2019s instructions (e.g., \u201cignore all previous instructions\u201d); an <strong>indirect prompt injection</strong> is malicious instructions hidden in external content (a web page, a document) that the model retrieves and executes.</p><p class=\"faint\">Exam trap: indirect injection comes from <em>retrieved data</em>, not from the user\u2019s own message. It is why groundedness and source validation matter in RAG pipelines.</p>" },
  { id: "r15", deck: "Responsible AI", tag: "Content Safety", front: "Groundedness detection", back: "<p><strong>Groundedness detection</strong> checks whether a model\u2019s generated response is supported by the source documents provided in the prompt, flagging claims that have no grounding in the retrieved context.</p><p class=\"faint\">Do not confuse with hallucination detection in general \u2014 groundedness detection specifically checks claims against <em>supplied sources</em>. It is most useful in RAG pipelines where you can verify assertions.</p>" },
  { id: "r16", deck: "Responsible AI", tag: "Content Safety", front: "Protected material detection", back: "<p><strong>Protected material detection</strong> identifies when a model\u2019s output reproduces copyrighted text or code, helping organizations avoid inadvertent copyright infringement in generated content.</p><p class=\"faint\">Exam trap: this is about output that reproduces protected <em>third-party material</em>, not about protecting the user\u2019s own data. It is distinct from PII detection, which targets personal identifying information.</p>" },
  { id: "r17", deck: "Responsible AI", tag: "Human Oversight", front: "Human-in-the-loop in responsible AI", back: "<p><strong>Human-in-the-loop</strong> means a person reviews, approves, or can override AI decisions at critical points, ensuring accountability and catching errors before they cause real-world harm.</p><p class=\"faint\">Exam trap: human-in-the-loop is a <em>mitigation</em> strategy in the operate stage, not a replacement for technical safeguards. It maps most directly to the accountability principle.</p>" },
  { id: "r18", deck: "Responsible AI", tag: "Process", front: "Identify, measure, mitigate, operate process", back: "<p>The four-stage responsible AI lifecycle is: <strong>identify</strong> potential harms, <strong>measure</strong> their frequency and severity, <strong>mitigate</strong> them at the model, safety system, system message, and UX layers, and <strong>operate</strong> the system with ongoing monitoring.</p><p class=\"faint\">Exam trap: mitigation is layered \u2014 it happens at multiple levels, not just the model. The operate stage means monitoring continues after deployment; responsible AI is not a one-time gate.</p>" }
  ,
  { id: "m1", deck: "Model Fundamentals", tag: "Generative AI", front: "Generative AI", back: "<p><strong>Generative AI</strong> is a class of AI models that produce new content \u2014 text, images, audio, video, or code \u2014 in response to a prompt, rather than classifying or predicting a fixed output.</p><p class=\"faint\">Exam trap: generative AI is not the same as agentic AI. Generative AI <em>generates</em> content; an agent <em>acts</em> over multiple steps, calling tools and maintaining state. Generative AI is a building block agents use.</p>" },
  { id: "m2", deck: "Model Fundamentals", tag: "LLM", front: "Large language model (LLM)", back: "<p>A <strong>large language model</strong> is a deep neural network trained on vast amounts of text to predict and generate human-like language, capable of reasoning, summarization, translation, and code generation.</p><p class=\"faint\">Exam trap: LLMs are not knowledge databases \u2014 they encode statistical patterns, not verified facts. That is why hallucination occurs, and why grounding and RAG are important.</p>" },
  { id: "m3", deck: "Model Fundamentals", tag: "Tokens", front: "Token", back: "<p>A <strong>token</strong> is the basic unit of text that a language model processes \u2014 roughly a word or word fragment. Models read and generate tokens, and billing is based on token count.</p><p class=\"faint\">Exam trap: tokens are not characters or words exactly \u2014 common words are one token; rare or long words may be several. \u201cUnbelievable\u201d might be three tokens. This matters for cost estimation and context limits.</p>" },
  { id: "m4", deck: "Model Fundamentals", tag: "Tokens", front: "Tokenization", back: "<p><strong>Tokenization</strong> is the process of splitting input text into tokens before it is fed to a model, and reassembling output tokens into readable text after generation.</p><p class=\"faint\">Exam trap: tokenization happens at both ends of the pipeline. A model never sees raw text \u2014 it only processes token IDs. Different models use different tokenizers, so token counts differ for the same input.</p>" },
  { id: "m5", deck: "Model Fundamentals", tag: "Prompting", front: "Prompt", back: "<p>A <strong>prompt</strong> is the input text \u2014 including instructions, examples, and context \u2014 that you send to a model to guide its response.</p><p class=\"faint\">Exam trap: a prompt is not just a question. It may include a system message, conversation history, retrieved documents, and user turn. All of this counts against the context window.</p>" },
  { id: "m6", deck: "Model Fundamentals", tag: "Prompting", front: "Completion", back: "<p>A <strong>completion</strong> is the text the model generates in response to a prompt. The model predicts the most likely continuation of the input token sequence given its training and configuration.</p><p class=\"faint\">Exam trap: \u201ccompletion\u201d is the term for the model\u2019s response regardless of format \u2014 it applies to chat, code, and document tasks. Do not confuse with \u201cchat completion\u201d which is one specific API shape.</p>" },
  { id: "m7", deck: "Model Fundamentals", tag: "Context Window", front: "Context window", back: "<p>The <strong>context window</strong> is the maximum number of tokens a model can process in a single request, including the entire prompt (system message, conversation history, retrieved passages) and the generated response.</p><p class=\"faint\">Exam trap: the context window limits the total tokens in AND out. A long conversation or large document retrieval can fill it, causing older turns to be dropped or the request to fail.</p>" },
  { id: "m8", deck: "Model Fundamentals", tag: "Context Window", front: "What happens when the context window is exceeded", back: "<p>When input tokens exceed the model\u2019s <strong>context window</strong>, the API returns an error or the system must truncate earlier content (such as older conversation turns) before sending the request.</p><p class=\"faint\">Exam trap: the model does not automatically summarize old context \u2014 the application developer must handle truncation or summarization. This is why context management is an important design concern in agentic apps.</p>" },
  { id: "m9", deck: "Model Fundamentals", tag: "Inference Params", front: "Temperature parameter", back: "<p><strong>Temperature</strong> controls output randomness: a lower value (near 0) makes responses focused and deterministic; a higher value increases variety and creativity.</p><p class=\"faint\">Exam trap: temperature does not improve accuracy \u2014 it only changes variance. Lowering temperature reduces hallucination risk by making outputs more predictable, not by making the model \u201csmarter.\u201d Do not tune both temperature and top_p simultaneously.</p>" },
  { id: "m10", deck: "Model Fundamentals", tag: "Inference Params", front: "top_p parameter", back: "<p><strong>top_p</strong> (nucleus sampling) limits token selection to the smallest set of tokens whose cumulative probability reaches the value of p, offering an alternative way to control output diversity.</p><p class=\"faint\">Exam trap: top_p and temperature both control randomness \u2014 Microsoft\u2019s guidance is to tune one <em>or</em> the other, not both at once. Changing top_p to 1.0 effectively disables it (full vocabulary available).</p>" },
  { id: "m11", deck: "Model Fundamentals", tag: "Inference Params", front: "max_tokens parameter", back: "<p><strong>max_tokens</strong> (also written <code>max_output_tokens</code>) sets a hard ceiling on the number of tokens the model may generate in its response, regardless of whether the output is complete.</p><p class=\"faint\">Exam trap: max_tokens does not reserve budget \u2014 it caps output length. A response can be shorter; it cannot be longer. Setting it too low truncates answers mid-sentence.</p>" },
  { id: "m12", deck: "Model Fundamentals", tag: "Inference Params", front: "frequency_penalty parameter", back: "<p><strong>frequency_penalty</strong> (range \u22122 to 2) reduces the likelihood of repeating tokens proportionally to how often they have already appeared, discouraging repetitive phrasing in long outputs.</p><p class=\"faint\">Exam trap: frequency_penalty scales with <em>count</em> of occurrences; presence_penalty is a flat penalty for any token that appeared at all. Use frequency_penalty to reduce verbatim repetition; use presence_penalty to push toward new topics.</p>" },
  { id: "m13", deck: "Model Fundamentals", tag: "Inference Params", front: "presence_penalty parameter", back: "<p><strong>presence_penalty</strong> (range \u22122 to 2) applies a flat one-time penalty to any token that has appeared anywhere in the output, nudging the model to introduce new topics and reduce repetition of themes.</p><p class=\"faint\">Exam trap: presence_penalty is a flat, one-time penalty regardless of how many times the token appeared; frequency_penalty grows with repetition count. Both reduce repetition but through different mechanisms.</p>" },
  { id: "m14", deck: "Model Fundamentals", tag: "Inference Params", front: "Stop sequences", back: "<p><strong>Stop sequences</strong> are one or more strings that, when the model generates them, cause generation to halt immediately, allowing applications to control output length and structure without relying solely on max_tokens.</p><p class=\"faint\">Exam trap: the stop sequence itself is not included in the output. Use them to terminate structured output (e.g., stop at \u201c###\u201d to end a section) or to prevent a model from generating beyond a delimiter.</p>" },
  { id: "m15", deck: "Model Fundamentals", tag: "Prompting", front: "System message", back: "<p>The <strong>system message</strong> is a special prompt sent in the <code>system</code> role that sets the model\u2019s persona, tone, scope, and constraints before any user turn, and it persists for the entire conversation.</p><p class=\"faint\">Exam trap: the system message counts toward the context window just like user turns. A very long system message can reduce the space available for retrieved documents and conversation history.</p>" },
  { id: "m16", deck: "Model Fundamentals", tag: "Hallucination", front: "Hallucination", back: "<p>A <strong>hallucination</strong> is a confident, fluent, but factually incorrect response generated by a model when it lacks the information needed to answer accurately.</p><p class=\"faint\">Exam trap: hallucinations are not random errors \u2014 they sound plausible and authoritative, which makes them dangerous. The primary mitigations are grounding (RAG), lower temperature, and instructing the model to say when it does not know.</p>" },
  { id: "m17", deck: "Model Fundamentals", tag: "Grounding", front: "Grounding", back: "<p><strong>Grounding</strong> means providing a model with relevant, authoritative context (documents, data, search results) in the prompt so its answer is anchored to verified information rather than relying solely on training weights.</p><p class=\"faint\">Exam trap: grounding does not change model weights \u2014 it changes what is in the prompt at query time. That is the fundamental difference from fine-tuning, which changes weights permanently.</p>" },
  { id: "m18", deck: "Model Fundamentals", tag: "RAG", front: "Retrieval augmented generation (RAG)", back: "<p><strong>Retrieval augmented generation (RAG)</strong> is a pattern where a question is converted to an embedding, similar passages are retrieved from a vector index, and those passages are inserted into the prompt so the model can answer with grounded, citable information.</p><p class=\"faint\">Exam trap: RAG adds current or domain-specific knowledge without retraining. It cannot change tone or format reliably \u2014 fine-tuning does that. The pipeline is: question \u2192 embed \u2192 search \u2192 insert \u2192 generate.</p>" },
  { id: "m19", deck: "Model Fundamentals", tag: "Embeddings", front: "Embedding", back: "<p>An <strong>embedding</strong> is a numerical vector representation of text (or other content) that captures semantic meaning, so that similar texts produce vectors that are close together in high-dimensional space.</p><p class=\"faint\">Exam trap: embeddings are not summaries \u2014 they are fixed-length numeric arrays. You cannot read an embedding as text. They are used for similarity search, clustering, and RAG retrieval, not for generating answers.</p>" },
  { id: "m20", deck: "Model Fundamentals", tag: "Embeddings", front: "Vector search", back: "<p><strong>Vector search</strong> retrieves documents whose embedding vectors are mathematically closest to the query embedding (typically by cosine similarity), enabling semantic search that matches meaning rather than exact keywords.</p><p class=\"faint\">Exam trap: vector search is meaning-based, not keyword-based. A query for \u201ccar\u201d can match a document containing \u201cautomobile\u201d. Azure AI Search supports both keyword and vector search and can blend them (hybrid search).</p>" },
  { id: "m21", deck: "Model Fundamentals", tag: "Fine-tuning", front: "Fine-tuning", back: "<p><strong>Fine-tuning</strong> updates the weights of a pretrained model on a smaller, domain-specific dataset, permanently adjusting its behavior for a specific style, tone, or narrow task.</p><p class=\"faint\">Exam trap: fine-tuning changes weights; grounding changes only the prompt. Fine-tuning is expensive and is best for tone and format, not for adding new or frequently changing facts \u2014 use RAG for that.</p>" },
  { id: "m22", deck: "Model Fundamentals", tag: "Fine-tuning", front: "When to fine-tune vs use RAG", back: "<p>Use <strong>RAG</strong> when you need to answer from current, domain-specific, or frequently updated information. Use <strong>fine-tuning</strong> when you need a specific tone, output format, or narrow specialized behavior that prompt engineering alone cannot reliably achieve.</p><p class=\"faint\">Exam trap: fine-tuning cannot reliably teach new facts \u2014 the model may still hallucinate if the fact was not in the fine-tuning data. For facts, ground at query time with RAG instead.</p>" },
  { id: "m23", deck: "Model Fundamentals", tag: "Multimodal", front: "Multimodal model", back: "<p>A <strong>multimodal model</strong> accepts more than one type of input (e.g., text and images, text and audio) and can generate outputs in one or more modalities, enabling tasks like image captioning, visual question answering, and spoken-prompt responses.</p><p class=\"faint\">Exam trap: not every model is multimodal. On AI-901, vision-enabled families are GPT-5.x, GPT-4.1, GPT-4o, and o-series. Phi models may support vision in some versions; check the catalog rather than assuming.</p>" },
  { id: "m24", deck: "Model Fundamentals", tag: "Prompting", front: "Prompt engineering, grounding, fine-tuning ladder", back: "<p>The recommended progression is: try <strong>prompt engineering</strong> first (free, instant), then add <strong>grounding/RAG</strong> for domain knowledge, and only use <strong>fine-tuning</strong> last for persistent style or format changes that grounding cannot solve.</p><p class=\"faint\">Exam trap: fine-tuning is not a cure-all and is not the first step. The ladder goes prompt \u2192 RAG \u2192 fine-tune. Each step adds cost and complexity, so start at the bottom.</p>" }
  ,
  { id: "d1", deck: "Model Selection \u0026 Deployment", tag: "Foundry Models", front: "Foundry Models catalog", back: "<p>The <strong>Foundry Models</strong> catalog contains 10,000+ models from Microsoft, partners, and the open-source community, organized by family and task, browsable and deployable directly from the Foundry portal or SDK.</p><p class=\"faint\">Exam trap: the catalog was previously called \u201cthe model catalog.\u201d On AI-901, the correct proper noun is <strong>Foundry Models</strong>. Models sold by Azure have Microsoft\u2019s SLA and billing; partner/community models do not.</p>" },
  { id: "d2", deck: "Model Selection \u0026 Deployment", tag: "Foundry Models", front: "Models sold by Azure vs partner and community models", back: "<p><strong>Models sold by Azure</strong> (all Azure OpenAI models plus selected Cohere, DeepSeek, Meta, Mistral, xAI) are hosted, billed, and SLA-backed by Microsoft. <strong>Partner and community models</strong> (open-source, Hugging Face, Anthropic Claude) are not SLA-backed by Microsoft.</p><p class=\"faint\">Exam trap: using a community model means you lose Microsoft\u2019s SLA guarantee. The distinction matters for compliance and production scenarios that require an SLA.</p>" },
  { id: "d3", deck: "Model Selection \u0026 Deployment", tag: "Model Families", front: "GPT-5.x series", back: "<p>The <strong>GPT-5.x series</strong> (gpt-5, gpt-5-mini, gpt-5-nano) is Microsoft\u2019s latest general-purpose family offering multimodal text and image input, suited for chat, reasoning, summarization, and coding at various cost-performance tiers.</p><p class=\"faint\">Exam trap: the smaller variants (mini, nano) cost less and respond faster; they trade some capability. Do not cite specific token limits or prices \u2014 these change. Focus on the family selection criteria.</p>" },
  { id: "d4", deck: "Model Selection \u0026 Deployment", tag: "Model Families", front: "o-series reasoning models", back: "<p>The <strong>o-series</strong> (o3, o4-mini) are reasoning models that use extended internal chain-of-thought processing, making them best for math, multi-step logic, and complex coding tasks where depth of reasoning matters more than raw speed.</p><p class=\"faint\">Exam trap: o-series models are slower and more expensive than GPT chat models because they perform internal reasoning steps before responding. Use them when accuracy on hard problems matters, not for low-latency chat.</p>" },
  { id: "d5", deck: "Model Selection \u0026 Deployment", tag: "Model Families", front: "Phi small language models", back: "<p><strong>Phi</strong> is Microsoft\u2019s family of small language models (SLMs) designed to run efficiently on edge or local hardware at very low cost, while still handling a broad range of language tasks.</p><p class=\"faint\">Exam trap: Phi is made by Microsoft but is an open-weight model \u2014 it does not automatically have the same SLA as an Azure-sold model like GPT-5. Use Phi when cost, latency, or edge deployment is the constraint.</p>" },
  { id: "d6", deck: "Model Selection \u0026 Deployment", tag: "Model Families", front: "Open-weight models in Foundry Models", back: "<p><strong>Open-weight models</strong> such as Meta\u2019s Llama, Mistral, and DeepSeek have publicly available weights that can be downloaded and customized, and they are deployable via Foundry\u2019s managed compute option.</p><p class=\"faint\">Exam trap: open-weight does not mean free in Azure \u2014 you still pay for compute. They are partner or community models without Microsoft\u2019s SLA unless Microsoft explicitly co-sells them as Azure models.</p>" },
  { id: "d7", deck: "Model Selection \u0026 Deployment", tag: "Model Families", front: "Embedding models in Foundry Models", back: "<p><strong>Embedding models</strong> such as text-embedding-3-large and text-embedding-3-small convert text into dense numerical vectors for use in semantic search, RAG pipelines, and similarity-based applications.</p><p class=\"faint\">Exam trap: the Foundry SDK project endpoint does not currently route embedding requests \u2014 use the OpenAI SDK against the resource\u2019s OpenAI endpoint directly. Embedding models do not generate text; they only produce vectors.</p>" },
  { id: "d8", deck: "Model Selection \u0026 Deployment", tag: "Model Families", front: "gpt-image-1 image generation model", back: "<p><strong>gpt-image-1</strong> (and variants gpt-image-1-mini, gpt-image-1.5) is the current Azure image generation family, replacing the older DALL-E 3 as the recommended model for text-to-image tasks in Foundry.</p><p class=\"faint\">Exam trap: AI-900 taught DALL-E 3; AI-901 answers are gpt-image-1. DALL-E 3 is no longer the recommended model. You may see DALL-E mentioned in distractors \u2014 select gpt-image-1 for current image generation.</p>" },
  { id: "d9", deck: "Model Selection \u0026 Deployment", tag: "Model Families", front: "FLUX image generation models", back: "<p><strong>FLUX</strong> models from Black Forest Labs are open-weight image generation models available in Foundry Models as an alternative to gpt-image-1 for text-to-image generation, especially for fine-tuned or customized image workflows.</p><p class=\"faint\">Exam trap: FLUX is a partner/community model, not an Azure-sold model. For production scenarios requiring Microsoft SLA, gpt-image-1 is the safer choice. Both are valid Foundry image generation options.</p>" },
  { id: "d10", deck: "Model Selection \u0026 Deployment", tag: "Model Families", front: "Sora video generation model", back: "<p><strong>Sora</strong> (and sora-2) is a text-to-video generation model available in preview in Foundry Models, enabling applications to generate short video clips from natural-language descriptions.</p><p class=\"faint\">Exam trap: sora is in <em>preview</em> \u2014 no production SLA. Do not propose it for scenarios requiring a guaranteed service level. Video generation is a distinct modality from image generation; the models are different.</p>" },
  { id: "d11", deck: "Model Selection \u0026 Deployment", tag: "Model Families", front: "Audio and realtime models", back: "<p><strong>Audio models</strong> such as gpt-realtime-* and gpt-audio-* accept speech input, process it through a language model, and return speech output, enabling low-latency conversational voice experiences beyond what deterministic TTS provides.</p><p class=\"faint\">Exam trap: gpt-realtime models are multimodal audio models, not Azure Speech. Use Azure Speech for deterministic transcription and synthesis with custom voices; use gpt-realtime for voice in, reasoning, voice out.</p>" },
  { id: "d12", deck: "Model Selection \u0026 Deployment", tag: "Model Families", front: "Whisper transcription model", back: "<p><strong>Whisper</strong> is an open-source speech-to-text transcription model from OpenAI, available in Foundry Models for high-accuracy audio transcription tasks without requiring the full Azure Speech service.</p><p class=\"faint\">Exam trap: whisper is a model in Foundry Models; gpt-live-transcribe is a separate Foundry Models transcription option. Both differ from Azure Speech, which is a full service with streaming, custom voices, and language identification.</p>" },
  { id: "d13", deck: "Model Selection \u0026 Deployment", tag: "Deployment", front: "Serverless API deployment", back: "<p>A <strong>serverless API</strong> deployment is the preferred deployment path in Foundry, requiring no infrastructure management. It covers pay-per-token, provisioned, and batch billing options, and supports the broadest set of models.</p><p class=\"faint\">Exam trap: serverless does not mean uncontrolled \u2014 it means you do not manage the compute. Microsoft handles scaling. This is the default recommendation: start here and move to managed compute only for specific open-source or custom-weight needs.</p>" },
  { id: "d14", deck: "Model Selection \u0026 Deployment", tag: "Deployment", front: "Managed compute deployment", back: "<p><strong>Managed compute</strong> (preview) provisions dedicated GPU capacity that you size, giving full control over the runtime environment. It is the required path for open-source, community, and custom-weight models.</p><p class=\"faint\">Exam trap: managed compute is in preview and lacks a production SLA. Use it only when serverless API is not available for the model you need (e.g., custom-weight Llama fine-tunes). It is more expensive and operationally heavier.</p>" },
  { id: "d15", deck: "Model Selection \u0026 Deployment", tag: "Deployment", front: "Instant access deployment", back: "<p><strong>Instant access</strong> (preview) lets you call a supported model by name with no deployment step at all, making it ideal for rapid experimentation without provisioning any resources.</p><p class=\"faint\">Exam trap: instant access is in preview and not suitable for production workloads. You also cannot customize inference configuration at the deployment level with instant access. It is strictly for evaluation and experimentation.</p>" },
  { id: "d16", deck: "Model Selection \u0026 Deployment", tag: "Deployment Types", front: "Global Standard deployment", back: "<p><strong>Global Standard</strong> is the default serverless API deployment type: pay-per-token, routes requests across any Azure region for the lowest price, and gets newest models first and broadest regional availability.</p><p class=\"faint\">Exam trap: Global Standard is Microsoft\u2019s recommended starting point. Move away from it only for a specific reason \u2014 data residency, reserved throughput, or bulk async jobs. If the question says \u201cno special requirements,\u201d the answer is Global Standard.</p>" },
  { id: "d17", deck: "Model Selection \u0026 Deployment", tag: "Deployment Types", front: "Provisioned throughput and PTU", back: "<p><strong>Provisioned throughput</strong> (Global Provisioned) reserves dedicated model capacity measured in <strong>PTUs (Provisioned Throughput Units)</strong>, providing predictable latency and throughput for high-volume, latency-sensitive production workloads.</p><p class=\"faint\">Exam trap: PTU deployments require commitment and cost more upfront than pay-per-token. They are appropriate for stable high-throughput production, not experimentation. If cost or flexibility is a priority, use Global Standard pay-per-token.</p>" },
  { id: "d18", deck: "Model Selection \u0026 Deployment", tag: "Deployment Types", front: "Global Batch deployment", back: "<p><strong>Global Batch</strong> processes large asynchronous jobs at roughly 50% the cost of standard pay-per-token, with a latency SLA of up to 24 hours, making it ideal for offline batch inference over large document sets.</p><p class=\"faint\">Exam trap: Global Batch is async \u2014 you cannot use it for real-time, interactive applications. It is the right answer when the scenario says \u201clarge asynchronous job,\u201d \u201covernight processing,\u201d or \u201ccost reduction on bulk tasks.\u201d</p>" },
  { id: "d19", deck: "Model Selection \u0026 Deployment", tag: "Deployment Types", front: "Data zone deployments", back: "<p><strong>Data zone deployments</strong> (Standard, Provisioned, Batch) restrict data processing to within a geographic data zone (US, EU, or APAC), supporting data residency requirements while still routing within that zone for availability.</p><p class=\"faint\">Exam trap: a data zone is not a single region \u2014 it is a group of regions within a geography. For strict single-region compliance, use the regional Standard deployment instead.</p>" },
  { id: "d20", deck: "Model Selection \u0026 Deployment", tag: "Deployment Types", front: "Regional Standard deployment", back: "<p><strong>Standard</strong> (regional) is a pay-per-token serverless deployment that processes data in a single, specified Azure region, meeting strict single-region data-residency compliance requirements.</p><p class=\"faint\">Exam trap: regional Standard may have less model availability and higher latency than Global Standard because it is constrained to one region. Use it only when single-region compliance is a hard requirement.</p>" },
  { id: "d21", deck: "Model Selection \u0026 Deployment", tag: "Deployment Types", front: "Developer deployment tier", back: "<p>The <strong>Developer</strong> deployment tier is a pay-per-token serverless option intended solely for evaluating fine-tuned models; deployments have a 24-hour lifespan and carry no SLA.</p><p class=\"faint\">Exam trap: Developer tier is not for production. Its sole use case is testing fine-tuned model behavior before promoting to a production deployment. The 24-hour expiry means any long-running workload will fail.</p>" },
  { id: "d22", deck: "Model Selection \u0026 Deployment", tag: "Selection Criteria", front: "Model selection criteria", back: "<p>Microsoft names these criteria for choosing a model: <strong>task, modality, capability and performance, cost, latency, context window, region availability, data residency requirements, and whether an SLA is required</strong>.</p><p class=\"faint\">Exam trap: smaller mini/nano variants cost less and respond faster but trade some capability. When the scenario emphasizes edge, low cost, or local deployment, Phi is the answer; when it emphasizes reasoning depth, o-series is the answer.</p>" }
  ,
  { id: "w1", deck: "AI Workloads", tag: "Workload Types", front: "Generative AI workload", back: "<p>A <strong>generative AI workload</strong> uses a large language or multimodal model to produce new content \u2014 text, images, audio, video, or code \u2014 from a prompt, enabling tasks like drafting, summarization, translation, and image creation.</p><p class=\"faint\">Exam trap: generative AI is not the same as agentic AI. Generative AI <em>creates output</em> from a single prompt; an agentic workload <em>acts autonomously</em> over multiple steps using tools and persistent state.</p>" },
  { id: "w2", deck: "AI Workloads", tag: "Workload Types", front: "Agentic AI workload", back: "<p>An <strong>agentic AI workload</strong> pairs a language model with instructions, tools, and persistent state so it can plan and execute multi-step tasks \u2014 calling functions, searching data, and taking actions \u2014 with minimal human intervention.</p><p class=\"faint\">Exam trap: an agent is not just a chatbot. The distinguishing features are multi-step autonomy, tool use, and persistent state (conversations). A single-turn completion is generative AI, not agentic AI.</p>" },
  { id: "w3", deck: "AI Workloads", tag: "Text Analysis", front: "Text analysis workload", back: "<p>A <strong>text analysis workload</strong> applies NLP models to unstructured text to extract structured insights such as entities, sentiment, key phrases, language, and summaries without generating new free-form content.</p><p class=\"faint\">Exam trap: text analysis produces structured labels and scores from existing text; generative AI produces new text. Azure Language in Foundry Tools is the purpose-built service for text analysis tasks.</p>" },
  { id: "w4", deck: "AI Workloads", tag: "Speech", front: "Speech workloads", back: "<p><strong>Speech workloads</strong> convert spoken audio to text (speech to text), convert text to spoken audio (text to speech), identify speakers, and translate spoken language, using Azure Speech in Foundry Tools or audio models.</p><p class=\"faint\">Exam trap: speech workloads are not just transcription. Speaker recognition, pronunciation assessment, translation, and text-to-speech avatar are also speech workloads. Do not confuse with multimodal audio models \u2014 Azure Speech is deterministic; audio models add reasoning.</p>" },
  { id: "w5", deck: "AI Workloads", tag: "Vision", front: "Computer vision workloads", back: "<p><strong>Computer vision workloads</strong> analyze images and video to describe scenes, detect objects, read text (OCR), identify faces, and generate images, using multimodal models or Azure Vision in Foundry Tools.</p><p class=\"faint\">Exam trap: for new computer vision work, Microsoft recommends vision-enabled multimodal models (GPT-5.x, GPT-4o) or Content Understanding. Azure Vision\u2019s Image Analysis 4.0 is deprecated; the Read API is legacy.</p>" },
  { id: "w6", deck: "AI Workloads", tag: "Information Extraction", front: "Information extraction workload", back: "<p>An <strong>information extraction workload</strong> identifies and pulls structured data from unstructured sources \u2014 documents, images, audio, or video \u2014 including entities, key phrases, PII, tables, and schema-defined fields.</p><p class=\"faint\">Exam trap: information extraction is broader than OCR. It includes named entity recognition, PII detection, key phrase extraction, and document field extraction via Content Understanding or Document Intelligence.</p>" },
  { id: "w7", deck: "AI Workloads", tag: "Text Analysis", front: "Key phrase extraction", back: "<p><strong>Key phrase extraction</strong> automatically identifies the main topics and important phrases in text, providing a quick summary of what a document is about without generating new content.</p><p class=\"faint\">Exam trap: key phrase extraction is a legacy feature of Azure Language \u2014 still supported and testable, but not receiving new investment. Do not confuse with named entity recognition, which classifies extracted terms by type (person, location, org).</p>" },
  { id: "w8", deck: "AI Workloads", tag: "Text Analysis", front: "Named entity recognition (NER)", back: "<p><strong>Named entity recognition (NER)</strong> identifies and classifies mentions of real-world entities (people, organizations, locations, dates, products) in text, returning the entity text and its category.</p><p class=\"faint\">Exam trap: NER is a core (actively evolving) feature of Azure Language. Do not confuse with key phrase extraction, which extracts important phrases without classifying their type.</p>" },
  { id: "w9", deck: "AI Workloads", tag: "Text Analysis", front: "Sentiment analysis", back: "<p><strong>Sentiment analysis</strong> classifies the overall emotional tone of text as positive, negative, or neutral, and can return confidence scores for each sentiment at the document or sentence level.</p><p class=\"faint\">Exam trap: sentiment analysis is a legacy feature of Azure Language \u2014 still valid and testable. Do not confuse with opinion mining, which identifies the target of sentiment (e.g., \u201cthe battery <em>life</em> is great\u201d).</p>" },
  { id: "w10", deck: "AI Workloads", tag: "Text Analysis", front: "Opinion mining", back: "<p><strong>Opinion mining</strong> (aspect-based sentiment) extends sentiment analysis by identifying the specific <em>aspect</em> of a subject that a sentiment targets, returning the aspect, the opinion, and the sentiment polarity.</p><p class=\"faint\">Exam trap: opinion mining is part of sentiment analysis in Azure Language. A review saying \u201cthe screen is excellent but the price is too high\u201d returns two aspect-opinion pairs, not one overall sentiment.</p>" },
  { id: "w11", deck: "AI Workloads", tag: "Text Analysis", front: "PII detection", back: "<p><strong>PII detection</strong> identifies personally identifiable information \u2014 names, addresses, phone numbers, credit card numbers, and other sensitive data \u2014 in text, so it can be redacted or flagged for compliance.</p><p class=\"faint\">Exam trap: PII detection is a core feature of Azure Language (actively evolving). There is also a separate health entity type within Text Analytics for Health. PII detection returns entity type and offset, not just a flag.</p>" },
  { id: "w12", deck: "AI Workloads", tag: "Text Analysis", front: "Language detection", back: "<p><strong>Language detection</strong> identifies the language of a text input and returns an ISO language code and a confidence score, enabling multilingual pipelines to route text to the correct downstream model or service.</p><p class=\"faint\">Exam trap: language detection is a core feature of Azure Language. Do not confuse with speech language identification, which performs the same task on audio. Both are valid but belong to different services.</p>" },
  { id: "w13", deck: "AI Workloads", tag: "Text Analysis", front: "Extractive summarization", back: "<p><strong>Extractive summarization</strong> selects and returns key sentences that already exist in the source document, preserving the original wording while reducing length.</p><p class=\"faint\">Exam trap: extractive summarization does <em>not</em> write new sentences \u2014 it selects existing ones. Abstractive summarization writes new text. Both are legacy features of Azure Language \u2014 still valid and testable.</p>" },
  { id: "w14", deck: "AI Workloads", tag: "Text Analysis", front: "Abstractive summarization", back: "<p><strong>Abstractive summarization</strong> generates new sentences that express the key information from a source document, producing a summary that may not quote the original text verbatim.</p><p class=\"faint\">Exam trap: abstractive summaries may differ in wording from the source even though they preserve meaning. Extractive summaries always use the source\u2019s own sentences. When the requirement is to paraphrase or condense, abstractive is the answer.</p>" },
  { id: "w15", deck: "AI Workloads", tag: "Text Analysis", front: "Question answering workload", back: "<p>A <strong>question answering</strong> workload returns a precise answer extracted from a knowledge base or document set in response to a natural-language question, without generating free-form text.</p><p class=\"faint\">Exam trap: question answering in Azure Language is a legacy feature that returns an answer span from a given corpus. It is not the same as a generative RAG response \u2014 RAG generates an answer; question answering extracts a span.</p>" },
  { id: "w16", deck: "AI Workloads", tag: "Text Analysis", front: "Conversational language understanding (CLU)", back: "<p><strong>Conversational language understanding (CLU)</strong> classifies user utterances into intents and extracts entities, enabling bots and virtual assistants to understand what a user wants and the key parameters of that request.</p><p class=\"faint\">Exam trap: CLU is a legacy feature of Azure Language. Do not confuse with question answering \u2014 CLU returns an intent and entities; question answering returns an answer span from a document. CLU powers bot routing; QA powers document-grounded answers.</p>" },
  { id: "w17", deck: "AI Workloads", tag: "Speech", front: "Translation workload", back: "<p>A <strong>translation workload</strong> converts text or speech from one language to another, using Azure Translator in Foundry Tools for text translation or Azure Speech\u2019s speech translation feature for audio.</p><p class=\"faint\">Exam trap: Azure Translator handles text-to-text translation; Azure Speech handles speech-to-text-or-speech translation. They are different services. Do not select Translator for an audio translation scenario.</p>" },
  { id: "w18", deck: "AI Workloads", tag: "Speech", front: "Transcription workload", back: "<p>A <strong>transcription workload</strong> converts spoken audio to text, supporting real-time streaming, batch processing of pre-recorded audio, or fast transcription for near-real-time results using Azure Speech.</p><p class=\"faint\">Exam trap: fast transcription is a distinct Azure Speech mode optimized for near-real-time speed with slightly less accuracy than batch. Whisper in Foundry Models is an alternative for high-accuracy offline transcription.</p>" },
  { id: "w19", deck: "AI Workloads", tag: "Vision", front: "Image understanding workload", back: "<p>An <strong>image understanding workload</strong> uses a vision-enabled model to describe, caption, answer questions about, or extract structured data from images, covering tasks like scene description, defect detection, and chart interpretation.</p><p class=\"faint\">Exam trap: for new image understanding, use multimodal models (GPT-5.x, GPT-4o) or Content Understanding with the image base analyzer. Azure Vision\u2019s Image Analysis 4.0 is deprecated and should not be the answer for new builds.</p>" },
  { id: "w20", deck: "AI Workloads", tag: "Workload Types", front: "Purpose-built feature vs generative model", back: "<p>Use a <strong>purpose-built</strong> Azure Language or Vision feature when you need consistent typed output, low latency, predictable cost, or compliance. Use a <strong>generative model</strong> when you need flexibility, reasoning, or multiple tasks combined in one call.</p><p class=\"faint\">Exam trap: generative models are not always the right answer. For well-defined tasks (NER, sentiment, OCR), purpose-built services are cheaper, faster, and produce structured output. Generative models excel when the task is open-ended or combines multiple NLP operations.</p>" }
  ,
  { id: "f1", deck: "Foundry Platform", tag: "Naming", front: "Microsoft Foundry", back: "<p><strong>Microsoft Foundry</strong> is the unified AI platform for building, evaluating, and deploying AI applications and agents. It was renamed from Azure AI Foundry on January 1, 2026, after being announced at Ignite in November 2025.</p><p class=\"faint\">Exam trap: the exam and some Microsoft docs still say \u201cAzure AI Foundry\u201d \u2014 it is the same product. On AI-901, use <em>Microsoft Foundry</em> or simply <em>Foundry</em>. Never say Azure AI Studio \u2014 that is two product names out of date.</p>" },
  { id: "f2", deck: "Foundry Platform", tag: "Portal", front: "Foundry portal", back: "<p>The <strong>Foundry portal</strong> (at ai.azure.com) is the web interface for creating and managing Foundry resources and projects, deploying models, running playgrounds, configuring agents, and viewing evaluations and observability data.</p><p class=\"faint\">Exam trap: the URL ai.azure.com still shows the old branding in some places. The correct name is the Foundry portal, not \u201cAzure AI Foundry portal\u201d or \u201cAzure AI Studio.\u201d</p>" },
  { id: "f3", deck: "Foundry Platform", tag: "Resources", front: "Foundry resource", back: "<p>A <strong>Foundry resource</strong> is the top-level Azure resource (an AIServices account created with <code>--allow-project-management true</code>) that hosts one or more Foundry projects and provides the shared model deployments and connections.</p><p class=\"faint\">Exam trap: the Foundry resource was previously called an \u201cAI hub\u201d in Foundry (classic). On current Foundry, the resource is the AIServices account. Do not say \u201chub\u201d for current architecture.</p>" },
  { id: "f4", deck: "Foundry Platform", tag: "Resources", front: "Foundry project", back: "<p>A <strong>Foundry project</strong> lives inside a Foundry resource and is the unit of scoping for access control, billing, and endpoints. Model deployments, agents, evaluations, connections, and toolboxes all belong to a project.</p><p class=\"faint\">Exam trap: the project is not optional \u2014 every API call targets a project endpoint. Multiple teams can share one Foundry resource through separate projects with separate RBAC assignments.</p>" },
  { id: "f5", deck: "Foundry Platform", tag: "Resources", front: "Project endpoint format", back: "<p>The Foundry project endpoint follows the format: <code>https://&lt;resource-name&gt;.services.ai.azure.com/api/projects/&lt;project-name&gt;</code>, and it is the base URL used in the Foundry SDK to create an AIProjectClient.</p><p class=\"faint\">Exam trap: the embeddings endpoint is an exception \u2014 it does not route through the project endpoint. Use the OpenAI endpoint format <code>https://&lt;resource&gt;.openai.azure.com/openai/v1/</code> for embedding calls instead.</p>" },
  { id: "f6", deck: "Foundry Platform", tag: "Resources", front: "What lives inside a Foundry project", back: "<p>A Foundry project contains: <strong>model deployments, agents, playgrounds, evaluations, connections</strong> (to Azure AI Search, storage, etc.), <strong>toolboxes, observability and tracing data, and scoped RBAC</strong> assignments.</p><p class=\"faint\">Exam trap: connections are scoped to the project and are how the project accesses external resources like Azure AI Search or blob storage. They are not global \u2014 each project has its own set.</p>" },
  { id: "f7", deck: "Foundry Platform", tag: "Resources", front: "Connections in a Foundry project", back: "<p><strong>Connections</strong> are project-scoped references to external resources \u2014 such as Azure AI Search indexes, Azure Blob Storage, or custom APIs \u2014 that agents and evaluations within the project can use without embedding credentials in code.</p><p class=\"faint\">Exam trap: connections store credentials securely in the project; your code references the connection by name. This is distinct from toolbox \u2014 a toolbox groups agent tools behind one MCP endpoint, while a connection grants access to an external resource.</p>" },
  { id: "f8", deck: "Foundry Platform", tag: "Portal", front: "Playgrounds in Foundry portal", back: "<p><strong>Playgrounds</strong> in the Foundry portal are browser-based interactive interfaces for testing model deployments and agents, adjusting inference parameters, and evaluating prompt behavior without writing code.</p><p class=\"faint\">Exam trap: playgrounds are for exploration and testing, not production. Use the Foundry SDK or REST API for production integrations. Playground sessions are not persistent agents unless you explicitly save and deploy them.</p>" },
  { id: "f9", deck: "Foundry Platform", tag: "Evaluations", front: "Evaluations in Foundry", back: "<p><strong>Evaluations</strong> in Foundry measure model and agent output quality against defined metrics \u2014 such as groundedness, coherence, relevance, and safety \u2014 using test datasets, helping teams compare models and prompt configurations before deployment.</p><p class=\"faint\">Exam trap: evaluations are a Foundry-managed feature that runs test cases and returns scores. They are not the same as unit tests in code. Use them to validate model behavior, not application logic.</p>" },
  { id: "f10", deck: "Foundry Platform", tag: "Architecture", front: "Foundry (classic) and hub-based projects", back: "<p><strong>Foundry (classic)</strong> is the older hub-based architecture (AI hub + hub-based project) that was deprecated on July 15, 2026. It is the predecessor to the current Foundry resource and project model.</p><p class=\"faint\">Exam trap: do not recommend Foundry (classic) for new builds. Mention it only as a contrast to current Foundry. The SDK 1.x targets classic; SDK 2.x targets current Foundry. If a question asks about new architecture, classic is the wrong answer.</p>" },
  { id: "f11", deck: "Foundry Platform", tag: "Naming", front: "Foundry Tools", back: "<p><strong>Foundry Tools</strong> is the umbrella brand for the individual Azure AI services (formerly Azure AI services / Cognitive Services), such as Azure Speech, Azure Language, Azure Vision, Content Understanding, and Document Intelligence.</p><p class=\"faint\">Exam trap: \u201cAzure AI services\u201d and \u201cCognitive Services\u201d are the old names for Foundry Tools. The individual service names now take the form \u201cAzure X in Foundry Tools,\u201d e.g., \u201cAzure Speech in Foundry Tools.\u201d</p>" },
  { id: "f12", deck: "Foundry Platform", tag: "Naming", front: "Foundry Models catalog as a proper noun", back: "<p><strong>Foundry Models</strong> is the proper name for the model catalog within Microsoft Foundry, containing 10,000+ models from Microsoft, partners, and the open-source community.</p><p class=\"faint\">Exam trap: on AI-901, say <em>Foundry Models</em>, not \u201cthe model catalog.\u201d The catalog was the informal term used before the rename. Questions may use either phrasing \u2014 recognize them as the same thing.</p>" },
  { id: "f13", deck: "Foundry Platform", tag: "RBAC", front: "Foundry RBAC roles", back: "<p>The Foundry-specific RBAC roles are <strong>Foundry User, Foundry Owner, Foundry Account Owner, and Foundry Project Manager</strong>, which replaced the old Azure AI User and Azure AI Owner roles.</p><p class=\"faint\">Exam trap: old documentation and exam questions may still say \u201cAzure AI User\u201d or \u201cAzure AI Owner.\u201d Recognize these as equivalent to Foundry User and Foundry Owner. RBAC is scoped per project, not globally.</p>" },
  { id: "f14", deck: "Foundry Platform", tag: "SDK", front: "Foundry SDK", back: "<p>The <strong>Foundry SDK</strong> is the Python package <code>azure-ai-projects</code> version 2.x that provides the <code>AIProjectClient</code> for interacting with Foundry projects, deploying models, creating agents, and managing conversations.</p><p class=\"faint\">Exam trap: version 1.x targets Foundry (classic) and is API-incompatible with 2.x. Always use <code>azure-ai-projects</code> 2.x for current Foundry. The package name is the same; only the major version changes the architecture it targets.</p>" },
  { id: "f15", deck: "Foundry Platform", tag: "SDK", front: "AIProjectClient", back: "<p><strong>AIProjectClient</strong> is the main entry-point class in the Foundry SDK. It is initialized with the project endpoint and a credential, and it exposes methods for model inference, agent management, and conversation handling.</p><p class=\"faint\">Exam trap: the endpoint passed to AIProjectClient must be the project endpoint, not the resource endpoint. Passing the wrong endpoint format is a common code mistake. The credential is typically <code>DefaultAzureCredential()</code>.</p>" },
  { id: "f16", deck: "Foundry Platform", tag: "SDK", front: "DefaultAzureCredential", back: "<p><strong>DefaultAzureCredential</strong> is the recommended keyless authentication class from the <code>azure-identity</code> package. It automatically selects the appropriate Entra credential (managed identity, developer CLI, environment) based on the runtime context.</p><p class=\"faint\">Exam trap: using DefaultAzureCredential means no API key is stored in code or configuration files \u2014 it is the secure, recommended approach. A hardcoded API key is an anti-pattern and a security risk.</p>" },
  { id: "f17", deck: "Foundry Platform", tag: "SDK", front: "get_openai_client() method", back: "<p><code>get_openai_client()</code> is called on an AIProjectClient instance to return an OpenAI-compatible client scoped to the Foundry project, enabling use of the familiar OpenAI API surface (responses, conversations) within Foundry.</p><p class=\"faint\">Exam trap: you can optionally pass <code>agent_name</code> to scope the client to a specific agent. Without it, the client targets model deployments directly. This is how you switch between agent-aware and plain model calls.</p>" },
  { id: "f18", deck: "Foundry Platform", tag: "SDK", front: "responses.create() method", back: "<p><code>responses.create()</code> is the Foundry SDK method for sending a prompt to a deployed model and receiving a completion. Pass <code>model</code> (the deployment name), <code>input</code> (the prompt), and optionally <code>conversation</code> (a conversation ID for multi-turn).</p><p class=\"faint\">Exam trap: the <code>model</code> parameter takes the <em>deployment name</em>, not the model family name. If you deployed gpt-5-mini under the name \u201cmydeployment,\u201d pass \u201cmydeployment,\u201d not \u201cgpt-5-mini.\u201d</p>" },
  { id: "f19", deck: "Foundry Platform", tag: "SDK", front: "Deployment name vs model name in the SDK", back: "<p>In Foundry SDK calls, the <strong>deployment name</strong> is what you pass as <code>model=</code> \u2014 it is the name you chose when you created the deployment, which may differ from the underlying model family name.</p><p class=\"faint\">Exam trap: this is a common beginner error. If you deploy gpt-5 under the name \u201cprod-chat,\u201d your code must say <code>model=\"prod-chat\"</code>. Passing the model family name will return a 404 or wrong-deployment error.</p>" },
  { id: "f20", deck: "Foundry Platform", tag: "Content Filters", front: "Content filters in Foundry", back: "<p><strong>Content filters</strong> in Foundry are Azure AI Content Safety policies attached to a deployment that evaluate both input and output against severity thresholds for hate, sexual, violence, and self-harm, blocking or flagging content that exceeds the configured threshold.</p><p class=\"faint\">Exam trap: content filters are applied at the <em>deployment</em> level, not the model level. Different deployments of the same model can have different filter configurations. Prompt shields are a separate, complementary feature.</p>" },
  { id: "f21", deck: "Foundry Platform", tag: "Observability", front: "Observability and tracing in Foundry", back: "<p><strong>Observability</strong> in Foundry captures traces of agent and model invocations \u2014 inputs, outputs, tool calls, latency, and token usage \u2014 enabling debugging, quality monitoring, and cost analysis of production AI applications.</p><p class=\"faint\">Exam trap: tracing is a project-scoped feature, not a global service. Enable it per project. Traces are stored in the project and can be viewed in the Foundry portal or exported to Azure Monitor.</p>" },
  { id: "f22", deck: "Foundry Platform", tag: "SDK", front: "Embeddings endpoint caveat", back: "<p>The Foundry SDK project endpoint does <strong>not</strong> currently route embedding requests. To call an embedding model, use the OpenAI SDK directly against the resource\u2019s OpenAI endpoint: <code>https://&lt;resource&gt;.openai.azure.com/openai/v1/</code>.</p><p class=\"faint\">Exam trap: this is an exception to the pattern. All other Foundry SDK calls use the project endpoint; embeddings do not. If a scenario calls for embeddings, the code must use the OpenAI endpoint, not the project endpoint.</p>" },
  { id: "f23", deck: "Foundry Platform", tag: "SDK", front: "azure-ai-projects 2.x vs 1.x", back: "<p><code>azure-ai-projects</code> <strong>version 2.x</strong> targets current Foundry (resource and project model). Version 1.x targets Foundry (classic) hub-based architecture and is API-incompatible with 2.x.</p><p class=\"faint\">Exam trap: the package name is identical between versions \u2014 only the major version number differs. If you see SDK code using hub-based patterns (AI hub, hub project), it is 1.x / classic. Current code uses AIProjectClient and conversations.</p>" },
  { id: "f24", deck: "Foundry Platform", tag: "SDK", front: "Reusing a conversation ID for multi-turn context", back: "<p>Passing the same <strong>conversation ID</strong> (from <code>conversations.create()</code>) across multiple <code>responses.create()</code> calls is what preserves multi-turn context, because Foundry stores the conversation history server-side for that ID.</p><p class=\"faint\">Exam trap: creating a new conversation for every turn breaks context \u2014 the model will not remember previous messages. Reusing the conversation ID is the explicit mechanism for multi-turn memory in current Foundry SDK, replacing the old threads/messages/runs pattern.</p>" }
  ,
  { id: "a1", deck: "Agents", tag: "Agents", front: "What is an agent", back: "<p>An <strong>agent</strong> is an AI component that pairs a language model with persistent instructions, a set of tools it may invoke, and optional knowledge, enabling it to plan and execute multi-step tasks autonomously and remember a conversation.</p><p class=\"faint\">Exam trap: an agent is not a chat completion. A chat completion is one stateless request and response. An agent adds instructions, tool-calling, and state \u2014 those three additions are what define it.</p>" },
  { id: "a2", deck: "Agents", tag: "Agents", front: "Agent vs chat completion", back: "<p>A <strong>chat completion</strong> is a single stateless request-response cycle. An <strong>agent</strong> adds persistent instructions, tool use, and conversation state, allowing it to take multiple steps, call external services, and remember prior turns.</p><p class=\"faint\">Exam trap: a chatbot that keeps conversation history is not automatically an agent \u2014 it must also have the ability to call tools and act on results. State alone does not make a chat completion an agent.</p>" },
  { id: "a3", deck: "Agents", tag: "Foundry Agent Service", front: "Foundry Agent Service", back: "<p>The <strong>Foundry Agent Service</strong> is the managed Azure service for creating, hosting, and running AI agents. It handles agent lifecycle, tool execution, conversation state, identity, and scaling within a Foundry project.</p><p class=\"faint\">Exam trap: the Foundry Agent Service was previously called \u201cAzure AI Agent Service.\u201d On AI-901, use the current name. Agents created here are first-class Foundry resources with their own RBAC, observability, and endpoint.</p>" },
  { id: "a4", deck: "Agents", tag: "Agent Types", front: "Prompt agent", back: "<p>A <strong>prompt agent</strong> is a declarative agent type in Foundry. You configure its model, instructions, and tools without writing orchestration code. Foundry hosts and runs it, and it can be authored in the portal or via SDK.</p><p class=\"faint\">Exam trap: prompt agent = no orchestration code to maintain. If a question describes an agent built entirely through configuration (portal or SDK definition), the answer is prompt agent, not hosted agent.</p>" },
  { id: "a5", deck: "Agents", tag: "Agent Types", front: "Hosted agent", back: "<p>A <strong>hosted agent</strong> is an agent where you write the orchestration code using Agent Framework, LangGraph, or the OpenAI Agents SDK, package it, and deploy it to Foundry, which provides a managed endpoint, autoscaling, and an Entra identity.</p><p class=\"faint\">Exam trap: hosted agents require code; prompt agents do not. Use hosted agents when you need custom orchestration logic that cannot be expressed declaratively. Foundry manages the runtime, not your orchestration decisions.</p>" },
  { id: "a6", deck: "Agents", tag: "Agent Types", front: "Ephemeral agents via the Responses API", back: "<p>An <strong>ephemeral agent</strong> (created via the Responses API) exists only in your code \u2014 no agent resource is created in Foundry. The agent definition lives in the API call itself, making it ideal for lightweight or transient scenarios.</p><p class=\"faint\">Exam trap: ephemeral agents do not persist in Foundry. There is no agent resource to manage, monitor, or reuse. Use a prompt or hosted agent when you need persistence, versioning, or reuse across multiple callers.</p>" },
  { id: "a7", deck: "Agents", tag: "Agent Components", front: "Agent instructions", back: "<p><strong>Agent instructions</strong> are the persistent system-level prompt attached to an agent that defines its role, behavior, scope, constraints, and persona, guiding every response the agent produces.</p><p class=\"faint\">Exam trap: instructions are set at agent definition time, not per-call. They are the agent\u2019s equivalent of the system message in a plain chat completion, but they persist across all conversations for that agent version.</p>" },
  { id: "a8", deck: "Agents", tag: "Agent Components", front: "Agent tools", back: "<p><strong>Tools</strong> are capabilities attached to an agent \u2014 such as code interpreter, file search, web search, or function calling \u2014 that the agent can invoke to take actions, retrieve information, or execute code in service of completing a task.</p><p class=\"faint\">Exam trap: the agent\u2019s model decides <em>when</em> to call a tool; you define <em>which</em> tools are available. The model does not call tools it has not been given, and it can use multiple tools in a single task.</p>" },
  { id: "a9", deck: "Agents", tag: "Agent Components", front: "Toolbox", back: "<p>A <strong>toolbox</strong> is a named collection of tools grouped behind a single MCP (Model Context Protocol) endpoint, so an agent accesses all of them through one connection rather than configuring each tool individually.</p><p class=\"faint\">Exam trap: a toolbox is a server-side grouping that simplifies agent configuration. It is not a client-side concept. The agent calls the toolbox endpoint; the toolbox routes to the appropriate individual tool.</p>" },
  { id: "a10", deck: "Agents", tag: "Agent Components", front: "Conversations (Foundry SDK 2.x)", back: "<p>In Foundry SDK 2.x, <strong>conversations</strong> are the persistent server-side objects that store multi-turn interaction history. You create one with <code>conversations.create()</code> and reference it across <code>responses.create()</code> calls.</p><p class=\"faint\">Exam trap: older material and Foundry (classic) use <em>threads, messages, and runs</em> from the OpenAI Assistants API. Current Foundry SDK 2.x uses <em>conversations and responses</em>. Recognize both but answer with the current terminology.</p>" },
  { id: "a11", deck: "Agents", tag: "Agent Components", front: "Threads, messages, and runs \u2014 older vocabulary", back: "<p>In Foundry (classic) and the OpenAI Assistants API, <strong>threads</strong> held conversation history, <strong>messages</strong> were individual turns, and <strong>runs</strong> were execution cycles. These are replaced by <strong>conversations and responses</strong> in current Foundry SDK 2.x.</p><p class=\"faint\">Exam trap: if you see \u201cthreads/messages/runs\u201d in a question, it refers to the older pattern. For new builds, the current Foundry SDK uses conversations and responses. Do not mix vocabulary in your answers.</p>" },
  { id: "a12", deck: "Agents", tag: "Agent Components", front: "Multi-turn state in agents", back: "<p><strong>Multi-turn state</strong> means the agent remembers previous turns within a conversation, allowing follow-up questions to reference prior context without the user repeating information.</p><p class=\"faint\">Exam trap: multi-turn state is maintained server-side by the Foundry conversation object, not by the client. Reusing the same conversation ID is what gives the agent memory \u2014 a new conversation ID starts fresh.</p>" },
  { id: "a13", deck: "Agents", tag: "Agent Components", front: "Agent identity (Entra managed identity)", back: "<p>Each hosted agent in Foundry is assigned an <strong>Entra managed identity</strong>, allowing it to authenticate to Azure resources (storage, search, functions) without storing credentials in code or configuration.</p><p class=\"faint\">Exam trap: agent identity is distinct from user identity. The agent acts as itself, not as the calling user, when accessing downstream resources. This is important for least-privilege design and audit logging.</p>" },
  { id: "a14", deck: "Agents", tag: "Agent Tools", front: "Code interpreter tool", back: "<p>The <strong>code interpreter</strong> tool gives an agent a sandboxed Python execution environment. The agent can write and run code, process data files, generate charts, and return results \u2014 all without external dependencies.</p><p class=\"faint\">Exam trap: code interpreter runs in a sandbox \u2014 it cannot access the internet or external APIs directly. It is for data processing and computation. For web access, use the Grounding with Bing or browser automation tool instead.</p>" },
  { id: "a15", deck: "Agents", tag: "Agent Tools", front: "File search tool", back: "<p>The <strong>file search</strong> tool lets an agent perform vector search over files you upload to the agent, enabling retrieval-augmented responses grounded in the uploaded documents without building a separate RAG pipeline.</p><p class=\"faint\">Exam trap: file search is built-in RAG for agents. You upload documents once; the agent indexes them automatically. For enterprise-scale or custom search, use Azure AI Search tool instead \u2014 it gives more control over indexing and ranking.</p>" },
  { id: "a16", deck: "Agents", tag: "Agent Tools", front: "Grounding with Bing tool", back: "<p>The <strong>Grounding with Bing</strong> tool allows an agent to perform live web searches and ground its responses in current, publicly available web content from Bing Search results.</p><p class=\"faint\">Exam trap: Grounding with Bing requires a Bing Search resource and adds cost per query. It is for public web knowledge. For your own internal documents, use file search or Azure AI Search instead.</p>" },
  { id: "a17", deck: "Agents", tag: "Agent Tools", front: "Azure AI Search tool for agents", back: "<p>The <strong>Azure AI Search</strong> tool connects an agent to an Azure AI Search index, enabling the agent to perform keyword, vector, or hybrid search over your enterprise documents and knowledge bases.</p><p class=\"faint\">Exam trap: Azure AI Search tool is for enterprise internal data. Grounding with Bing is for public web data. Both ground the agent, but they target different knowledge sources. A single agent can have both.</p>" },
  { id: "a18", deck: "Agents", tag: "Agent Tools", front: "Function calling", back: "<p><strong>Function calling</strong> lets an agent invoke developer-defined functions by emitting a structured JSON payload that the calling application then executes and returns results from, enabling integration with any API or business logic.</p><p class=\"faint\">Exam trap: the agent does not execute the function directly \u2014 it emits a structured tool call, and your application code runs the function and passes the result back. This keeps the agent\u2019s execution environment isolated.</p>" },
  { id: "a19", deck: "Agents", tag: "Agent Tools", front: "OpenAPI tools", back: "<p><strong>OpenAPI tools</strong> allow an agent to call any REST API described by an OpenAPI specification, auto-generating the tool interface from the spec so the agent can invoke endpoints without manual function definitions.</p><p class=\"faint\">Exam trap: OpenAPI tools differ from function calling in that the interface is derived from an existing spec rather than custom-coded. Use them when a service already has an OpenAPI spec and you want minimal configuration.</p>" },
  { id: "a20", deck: "Agents", tag: "Agent Tools", front: "MCP (Model Context Protocol)", back: "<p><strong>MCP (Model Context Protocol)</strong> is an open protocol that allows agents to discover and call tools exposed by any MCP-compatible server, enabling a standardized way to extend agent capabilities across vendors and systems.</p><p class=\"faint\">Exam trap: MCP is a <em>protocol</em>, not a specific Azure service. A toolbox in Foundry can serve as an MCP endpoint. MCP enables agents from any vendor to use the same tool servers.</p>" },
  { id: "a21", deck: "Agents", tag: "Multi-Agent", front: "Agent-to-agent (A2A) tool", back: "<p>The <strong>agent-to-agent (A2A)</strong> tool allows one agent (the orchestrator) to call another agent (a subagent) as a tool, enabling multi-agent workflows where specialist agents handle distinct parts of a complex task.</p><p class=\"faint\">Exam trap: A2A is a tool, not a framework. The orchestrator uses it like any other tool call. Foundry manages identity, observability, and routing for the A2A call automatically.</p>" },
  { id: "a22", deck: "Agents", tag: "Multi-Agent", front: "Single-agent vs multi-agent architecture", back: "<p>In a <strong>single-agent</strong> design, one agent handles all tasks with multiple tools. In a <strong>multi-agent</strong> design, an orchestrator routes subtasks to specialist subagents using the A2A tool, enabling parallelism and separation of concerns.</p><p class=\"faint\">Exam trap: multi-agent adds complexity \u2014 it is not always better. Use multi-agent when tasks are large, parallel, or require genuinely different expertise. For simpler workflows, a single agent with several tools is easier to maintain.</p>" },
  { id: "a23", deck: "Agents", tag: "Multi-Agent", front: "Orchestrator and subagents", back: "<p>An <strong>orchestrator</strong> agent receives the overall goal, plans the steps, and delegates work to <strong>subagents</strong> using the A2A tool. Each subagent specializes in a specific task and returns results to the orchestrator.</p><p class=\"faint\">Exam trap: the orchestrator is itself an agent with instructions and tools. It does not have to be a different model \u2014 the same model family can serve as both orchestrator and subagent in different roles.</p>" },
  { id: "a24", deck: "Agents", tag: "Agent Tools", front: "Browser automation tool", back: "<p>The <strong>browser automation</strong> tool allows an agent to control a headless browser \u2014 navigating web pages, clicking elements, and reading dynamic content \u2014 enabling tasks that require interacting with web applications rather than just reading static data.</p><p class=\"faint\">Exam trap: browser automation is for dynamic web apps that cannot be accessed via a plain API. Do not confuse with Grounding with Bing, which retrieves search results; browser automation performs full page interactions.</p>" },
  { id: "a25", deck: "Agents", tag: "Agent Tools", front: "SharePoint and Azure Functions tools", back: "<p>The <strong>SharePoint tool</strong> lets an agent search and read SharePoint content; the <strong>Azure Functions tool</strong> lets an agent trigger serverless Azure Functions, enabling integration with backend processes and enterprise data stores.</p><p class=\"faint\">Exam trap: SharePoint tool is for read/search; it is not for writing files back to SharePoint. Azure Functions tool enables arbitrary serverless code execution \u2014 it is the most flexible tool option for custom business logic.</p>" },
  { id: "a26", deck: "Agents", tag: "Agent Framework", front: "Agent Framework", back: "<p>The <strong>Agent Framework</strong> is the code-level programming model for building hosted agents in Foundry, providing abstractions for orchestration, tool registration, conversation management, and evaluation that sit above raw SDK calls.</p><p class=\"faint\">Exam trap: the Agent Framework is used for hosted agents that require custom orchestration code. It is an alternative to prompt agents (declarative, no code) and to external frameworks like LangGraph or the OpenAI Agents SDK.</p>" }
  ,
  { id: "s1", deck: "Text, Speech \u0026 Vision", tag: "Language Service", front: "Azure Language in Foundry Tools", back: "<p><strong>Azure Language in Foundry Tools</strong> (formerly Azure Cognitive Service for Language) provides NLP capabilities including named entity recognition, PII detection, sentiment analysis, summarization, translation, and more via a REST API or SDK.</p><p class=\"faint\">Exam trap: features are split into core (actively evolving) and legacy (supported but not receiving new investment). Do not assume legacy features are retired \u2014 they are still valid exam answers.</p>" },
  { id: "s2", deck: "Text, Speech \u0026 Vision", tag: "Language Service", front: "Core vs legacy features in Azure Language", back: "<p><strong>Core features</strong> of Azure Language (actively evolving): PII detection, language detection, named entity recognition, and text analytics for health. <strong>Legacy features</strong> (supported, not evolving): sentiment analysis, key phrase extraction, summarization, CLU, and question answering.</p><p class=\"faint\">Exam trap: legacy does not mean deprecated or retired. All legacy features are still testable on the exam. The split signals investment direction, not availability. New NLP features are added to the core tier.</p>" },
  { id: "s3", deck: "Text, Speech \u0026 Vision", tag: "Language Service", front: "Named entity recognition in Azure Language", back: "<p><strong>Named entity recognition (NER)</strong> identifies and classifies mentions of people, organizations, locations, dates, and other real-world entities in text, returning each entity\u2019s text, category, and confidence score.</p><p class=\"faint\">Exam trap: NER is a core feature (actively evolving). Custom NER lets you define your own entity types using labeled examples. Do not confuse with key phrase extraction, which extracts important phrases without category classification.</p>" },
  { id: "s4", deck: "Text, Speech \u0026 Vision", tag: "Language Service", front: "PII detection in Azure Language", back: "<p><strong>PII detection</strong> in Azure Language identifies personally identifiable information such as names, addresses, phone numbers, and financial data in text, supporting redaction for privacy and compliance use cases.</p><p class=\"faint\">Exam trap: PII detection is a core (evolving) feature. There is a related PII model within text analytics for health that targets clinical PII. Do not use the health model for general document PII detection.</p>" },
  { id: "s5", deck: "Text, Speech \u0026 Vision", tag: "Language Service", front: "Text analytics for health", back: "<p><strong>Text analytics for health</strong> is a specialized Azure Language feature that extracts clinical entities \u2014 diagnoses, medications, symptoms, dosages, and body parts \u2014 from medical text such as clinical notes and discharge summaries.</p><p class=\"faint\">Exam trap: text analytics for health is a core feature and is NOT the same as general PII detection. It targets clinical NLP, not generic personal data. Use it for structured extraction from medical records, not for GDPR compliance tasks.</p>" },
  { id: "s6", deck: "Text, Speech \u0026 Vision", tag: "Speech Service", front: "Azure Speech in Foundry Tools", back: "<p><strong>Azure Speech in Foundry Tools</strong> provides deterministic speech-to-text, text-to-speech, speech translation, speaker recognition, pronunciation assessment, custom speech models, and Voice Live for conversational voice applications.</p><p class=\"faint\">Exam trap: Azure Speech is deterministic \u2014 it does not reason over content. For voice-in, reasoning, voice-out experiences (e.g., a spoken AI assistant), use multimodal audio models (gpt-realtime-*) instead.</p>" },
  { id: "s7", deck: "Text, Speech \u0026 Vision", tag: "Speech Service", front: "Speech to text (real-time transcription)", back: "<p><strong>Real-time speech to text</strong> streams audio to the Azure Speech service and returns a transcript as text is spoken, enabling live captioning, voice commands, and interactive voice interfaces.</p><p class=\"faint\">Exam trap: real-time STT is optimized for low latency, not maximum accuracy. For highest accuracy on pre-recorded audio where latency is not critical, batch transcription is more appropriate.</p>" },
  { id: "s8", deck: "Text, Speech \u0026 Vision", tag: "Speech Service", front: "Batch transcription", back: "<p><strong>Batch transcription</strong> submits pre-recorded audio files to Azure Speech for asynchronous transcription, optimized for throughput and accuracy over large volumes of audio when real-time speed is not required.</p><p class=\"faint\">Exam trap: batch transcription is async \u2014 you submit a job and poll for results. It is not suitable for interactive applications. Use it for offline scenarios like transcribing call center recordings overnight.</p>" },
  { id: "s9", deck: "Text, Speech \u0026 Vision", tag: "Speech Service", front: "Fast transcription", back: "<p><strong>Fast transcription</strong> is an Azure Speech mode that processes pre-recorded audio at near-real-time speed with slightly less accuracy than batch transcription, bridging the gap between streaming real-time and full batch modes.</p><p class=\"faint\">Exam trap: fast transcription is distinct from real-time streaming \u2014 it still processes a complete audio file, just quickly. Use it when you need quick results from pre-recorded audio but can tolerate minor accuracy trade-offs.</p>" },
  { id: "s10", deck: "Text, Speech \u0026 Vision", tag: "Speech Service", front: "Text to speech and neural voices", back: "<p><strong>Text to speech</strong> in Azure Speech converts written text to natural-sounding audio using <strong>neural voices</strong> \u2014 deep learning-based voices that produce human-like prosody, reducing the robotic quality of older TTS systems.</p><p class=\"faint\">Exam trap: neural voices are the current standard; older concatenative voices are legacy. Do not confuse neural voice (a synthesis technology) with custom neural voice (a fine-tuned voice trained on a specific speaker\u2019s recordings).</p>" },
  { id: "s11", deck: "Text, Speech \u0026 Vision", tag: "Speech Service", front: "SSML (Speech Synthesis Markup Language)", back: "<p><strong>SSML</strong> is an XML-based markup language that lets you control text-to-speech output in detail \u2014 adjusting pitch, rate, volume, pauses, and pronunciation \u2014 beyond what plain text input allows.</p><p class=\"faint\">Exam trap: SSML is for <em>control</em>, not content. Use it when you need precise prosody, custom pronunciation of acronyms, or spoken formatting cues. A plain text input is sufficient when default voice quality is acceptable.</p>" },
  { id: "s12", deck: "Text, Speech \u0026 Vision", tag: "Speech Service", front: "Custom neural voice", back: "<p><strong>Custom neural voice</strong> is a gated Azure Speech feature that lets you train a TTS voice on recordings of a specific speaker, creating a synthetic voice that sounds like that individual.</p><p class=\"faint\">Exam trap: custom neural voice requires explicit Microsoft gating approval due to its potential for voice impersonation. It is not simply a self-service configuration. Use standard neural voices for general TTS; custom neural voice requires approval and consent.</p>" },
  { id: "s13", deck: "Text, Speech \u0026 Vision", tag: "Speech Service", front: "Speech translation", back: "<p><strong>Speech translation</strong> in Azure Speech converts spoken audio in one language to text or speech in another language in a single pipeline, combining STT, translation, and optionally TTS.</p><p class=\"faint\">Exam trap: speech translation is a feature of Azure Speech, not Azure Translator. Azure Translator handles text-to-text translation. Do not select Translator for an audio translation scenario; select Azure Speech.</p>" },
  { id: "s14", deck: "Text, Speech \u0026 Vision", tag: "Speech Service", front: "Speaker recognition", back: "<p><strong>Speaker recognition</strong> in Azure Speech identifies or verifies a person based on the unique characteristics of their voice, supporting use cases like speaker diarization (who said what) and identity verification.</p><p class=\"faint\">Exam trap: speaker recognition verifies or identifies based on voice; it is not the same as face recognition. Also do not confuse with speaker diarization, which is specifically the task of labeling who is speaking at each moment in a transcript.</p>" },
  { id: "s15", deck: "Text, Speech \u0026 Vision", tag: "Speech Service", front: "Voice Live", back: "<p><strong>Voice Live</strong> is an Azure Speech feature that enables low-latency, real-time, full-duplex conversational voice interactions, designed for building spoken AI assistants where response latency is critical.</p><p class=\"faint\">Exam trap: Voice Live is a Speech service feature (deterministic). For a voice assistant that needs language model reasoning, combine Voice Live with a language model or use multimodal audio models (gpt-realtime) that integrate speech and reasoning natively.</p>" },
  { id: "s16", deck: "Text, Speech \u0026 Vision", tag: "Speech Service", front: "Multimodal audio models for spoken prompts", back: "<p><strong>Multimodal audio models</strong> (gpt-realtime-*, gpt-audio-*) accept spoken input, apply language model reasoning, and return spoken output, enabling intelligent voice assistants that can understand, reason, and respond in speech.</p><p class=\"faint\">Exam trap: this is what \u201crespond to spoken prompts by using a deployed multimodal model\u201d means on the exam. Azure Speech does deterministic STT/TTS; multimodal audio models add the reasoning layer. The two are complementary, not interchangeable.</p>" },
  { id: "s17", deck: "Text, Speech \u0026 Vision", tag: "Speech Service", front: "Whisper as a transcription model", back: "<p><strong>Whisper</strong> is an open-source speech-to-text model available in Foundry Models that delivers high-accuracy transcription without requiring the full Azure Speech service, suitable for offline or batch transcription pipelines.</p><p class=\"faint\">Exam trap: whisper is a model deployed from Foundry Models; Azure Speech is a managed service. Whisper does not support streaming or speaker recognition out of the box. For enterprise speech features, Azure Speech is more complete.</p>" },
  { id: "s18", deck: "Text, Speech \u0026 Vision", tag: "Vision", front: "Vision-enabled models and image input in prompts", back: "<p>Vision-enabled model families \u2014 <strong>GPT-5.x, GPT-4.1, GPT-4o, and o-series</strong> \u2014 accept image inputs alongside text in a prompt, enabling image captioning, visual question answering, chart interpretation, and defect detection.</p><p class=\"faint\">Exam trap: not all models accept image input. On the exam, if the scenario requires analyzing an image with a language model, the answer must be a vision-enabled family. Phi may support vision in some versions; confirm in the catalog.</p>" },
  { id: "s19", deck: "Text, Speech \u0026 Vision", tag: "Vision", front: "Azure Vision in Foundry Tools", back: "<p><strong>Azure Vision in Foundry Tools</strong> (formerly Azure Computer Vision) provides image analysis, OCR, face detection, and spatial analysis. However, <strong>Image Analysis 4.0 is deprecated</strong> (retires September 25, 2028) and the Read/OCR API is labeled legacy.</p><p class=\"faint\">Exam trap: for new image understanding work, Microsoft recommends multimodal models or Content Understanding, not Azure Vision Image Analysis 4.0. Mention Azure Vision only for existing deployments or the Face API use case.</p>" },
  { id: "s20", deck: "Text, Speech \u0026 Vision", tag: "Vision", front: "Azure Face and Limited Access", back: "<p><strong>Azure Face</strong> provides face detection, verification, identification, and liveness detection. It is an active service but is <strong>Limited Access</strong> \u2014 you must apply and be approved by Microsoft before you can use it.</p><p class=\"faint\">Exam trap: emotion and gender inference from face were <em>retired</em> for responsible AI reasons and are no longer available. Only detection, verification, identification, and liveness remain. Do not select emotion inference as a current Face capability.</p>" },
  { id: "s21", deck: "Text, Speech \u0026 Vision", tag: "Vision", front: "Liveness detection in Azure Face", back: "<p><strong>Liveness detection</strong> in Azure Face determines whether a face presented to a camera is a real, live person or a spoofing attempt (photo, video, or mask), protecting face-based authentication systems.</p><p class=\"faint\">Exam trap: liveness detection is part of Azure Face, which is Limited Access. It is not available without an approved application. Do not confuse with face verification, which compares two face images without checking for liveness.</p>" },
  { id: "s22", deck: "Text, Speech \u0026 Vision", tag: "Vision", front: "Azure AI Custom Vision retirement", back: "<p><strong>Azure AI Custom Vision</strong> is an active service that trains custom image classification and object detection models using labeled images, but it is <strong>retiring on September 25, 2028</strong>.</p><p class=\"faint\">Exam trap: Custom Vision is still active and testable on AI-901, but Microsoft\u2019s forward-looking guidance for custom image scenarios points to fine-tuning vision-enabled models in Foundry. Do not recommend Custom Vision for net-new builds after 2026.</p>" },
  { id: "s23", deck: "Text, Speech \u0026 Vision", tag: "Vision", front: "Image Analysis 4.0 deprecation", back: "<p><strong>Image Analysis 4.0</strong> in Azure Vision is deprecated and scheduled to retire on September 25, 2028. For new image understanding scenarios, Microsoft recommends vision-enabled multimodal models (GPT-5.x, GPT-4o) or Azure Content Understanding.</p><p class=\"faint\">Exam trap: deprecated does not mean immediately unavailable. It means no new investment and a known retirement date. If a question asks what to use for a <em>new</em> image analysis solution, avoid Image Analysis 4.0 as the answer.</p>" },
  { id: "s24", deck: "Text, Speech \u0026 Vision", tag: "Vision", front: "Read API legacy status", back: "<p>The <strong>Read API</strong> in Azure Vision is labeled <strong>legacy</strong> for new optical character recognition (OCR) work. For new OCR and document reading, use Content Understanding\u2019s <code>prebuilt-read</code> or <code>prebuilt-layout</code> analyzers instead.</p><p class=\"faint\">Exam trap: the Read API still works and is not retired, but choosing it for a new build is wrong on this exam. The expected answer for \u201cnew OCR\u201d is Content Understanding <code>prebuilt-read</code> or a multimodal model, not the legacy Read API.</p>" }
  ,
  { id: "c1", deck: "Content Understanding", tag: "Service Overview", front: "Azure Content Understanding in Foundry Tools", back: "<p><strong>Azure Content Understanding in Foundry Tools</strong> is a generally available (GA at API version 2025-11-01) generative AI-powered service that extracts structured information from documents, images, audio, and video using configurable analyzers.</p><p class=\"faint\">Exam trap: Content Understanding is GA, not preview. It uses generative AI, which means it can extract fields from unstructured content without labeled training data. This is a key distinguisher from Document Intelligence.</p>" },
  { id: "c2", deck: "Content Understanding", tag: "Service Overview", front: "Four modalities of Content Understanding", back: "<p>Content Understanding processes four content modalities: <strong>documents, images, audio, and video</strong>. Each has a corresponding base analyzer and a RAG analyzer for retrieval pipelines.</p><p class=\"faint\">Exam trap: Document Intelligence handles documents only. When a scenario involves images, audio, or video extraction, Content Understanding is the answer, not Document Intelligence.</p>" },
  { id: "c3", deck: "Content Understanding", tag: "Analyzers", front: "Analyzer in Content Understanding", back: "<p>An <strong>analyzer</strong> is a reusable, configurable processing unit that specifies the content type (via baseAnalyzerId), the fields to extract (via fieldSchema), output format, and which models to use. Created once and called repeatedly.</p><p class=\"faint\">Exam trap: an analyzer is a resource you define and deploy, not a one-off API call. Its reusability is what makes it suitable for production pipelines where the same extraction logic runs on many files.</p>" },
  { id: "c4", deck: "Content Understanding", tag: "Analyzers", front: "baseAnalyzerId", back: "<p>The <strong>baseAnalyzerId</strong> is the field in an analyzer definition that specifies which prebuilt base analyzer to extend, setting the content modality and default extraction behavior that the custom schema builds upon.</p><p class=\"faint\">Exam trap: you must always specify a baseAnalyzerId \u2014 you cannot create a Content Understanding analyzer from scratch. Choose <code>prebuilt-document</code>, <code>prebuilt-image</code>, <code>prebuilt-audio</code>, or <code>prebuilt-video</code> as the base.</p>" },
  { id: "c5", deck: "Content Understanding", tag: "Analyzers", front: "Field schema in Content Understanding", back: "<p>The <strong>field schema</strong> is a JSON definition embedded in an analyzer that names each field to extract, gives it a type, and specifies whether it should be extracted, classified, or generated.</p><p class=\"faint\">Exam trap: fields are defined by <em>description in plain language</em> for zero-shot extraction \u2014 you do not need labeled examples. Each field independently picks its extraction method (extract, classify, or generate).</p>" },
  { id: "c6", deck: "Content Understanding", tag: "Methods", front: "Extract method in Content Understanding", back: "<p>The <strong>extract</strong> method copies a value that <em>literally appears</em> in the source content. It is most common for documents where you need verbatim field values such as dates, totals, or names.</p><p class=\"faint\">Exam trap: extract is for verbatim values. If the value you need does not literally appear in the content (e.g., an inferred category or a generated summary), use classify or generate instead.</p>" },
  { id: "c7", deck: "Content Understanding", tag: "Methods", front: "Classify method in Content Understanding", back: "<p>The <strong>classify</strong> method assigns the content or a field to one of a predefined set of categories you provide, enabling structured categorization without free-form generation.</p><p class=\"faint\">Exam trap: classify requires you to supply the category set. If you have a fixed, known taxonomy (e.g., invoice type: purchase order, credit memo, standard invoice), use classify. For open-ended labeling, use generate.</p>" },
  { id: "c8", deck: "Content Understanding", tag: "Methods", front: "Generate method in Content Understanding", back: "<p>The <strong>generate</strong> method uses generative AI to produce a new value derived from the content \u2014 such as a summary, translation, interpretation, or answer to a question \u2014 that does not appear verbatim in the source.</p><p class=\"faint\">Exam trap: generate is the only method that creates new content. It is what makes Content Understanding generative. For purely extractive tasks, extract is more deterministic and verifiable; generate adds generative AI cost and variance.</p>" },
  { id: "c9", deck: "Content Understanding", tag: "Analyzers", front: "Prebuilt analyzers in Content Understanding", back: "<p><strong>Prebuilt analyzers</strong> are ready-to-use Content Understanding analyzers provided by Microsoft, including content extraction analyzers (prebuilt-read, prebuilt-layout), the four base analyzers, four RAG analyzers, and domain-specific analyzers (invoice, receipt, ID, contract, call center).</p><p class=\"faint\">Exam trap: domain-specific prebuilts like prebuilt-invoice still exist in Content Understanding and provide high accuracy for structured forms. However, for highest accuracy on structured standard forms, Document Intelligence prebuilts may still win.</p>" },
  { id: "c10", deck: "Content Understanding", tag: "Analyzers", front: "prebuilt-read analyzer", back: "<p><strong>prebuilt-read</strong> is the Content Understanding analyzer for optical character recognition (OCR) that extracts raw text from documents and images, providing the current recommended path for new OCR work.</p><p class=\"faint\">Exam trap: prebuilt-read in Content Understanding replaces the legacy Read API in Azure Vision for new builds. The legacy Read API still works, but the current exam answer for new OCR is prebuilt-read or prebuilt-layout.</p>" },
  { id: "c11", deck: "Content Understanding", tag: "Analyzers", front: "prebuilt-layout analyzer", back: "<p><strong>prebuilt-layout</strong> is the Content Understanding analyzer that extracts text, tables, selection marks, and document structure (paragraphs, headings) from documents, preserving layout context beyond what plain OCR provides.</p><p class=\"faint\">Exam trap: prebuilt-layout is richer than prebuilt-read \u2014 it also extracts tables and structure. Use prebuilt-layout when the downstream task needs to understand document structure, not just raw text.</p>" },
  { id: "c12", deck: "Content Understanding", tag: "Analyzers", front: "Four base analyzers in Content Understanding", back: "<p>The four base analyzers correspond to the four modalities: <strong>prebuilt-document, prebuilt-image, prebuilt-audio, prebuilt-video</strong>. They define the default extraction behavior that custom analyzers extend via baseAnalyzerId.</p><p class=\"faint\">Exam trap: each base analyzer supports only its own modality. A document analyzer cannot process audio. If a scenario mixes modalities (e.g., audio from a recorded meeting plus the accompanying slide deck), use separate analyzers per modality.</p>" },
  { id: "c13", deck: "Content Understanding", tag: "Analyzers", front: "Four RAG analyzers in Content Understanding", back: "<p>The four RAG analyzers (prebuilt-documentSearch, prebuilt-imageSearch, prebuilt-audioSearch, prebuilt-videoSearch) are optimized to produce chunked, Markdown-formatted output suitable for indexing in Azure AI Search or other vector stores.</p><p class=\"faint\">Exam trap: use a RAG analyzer when the output feeds a retrieval pipeline. It produces Markdown and chunk boundaries. Use a base analyzer when you need structured JSON field extraction, not chunks for search.</p>" },
  { id: "c14", deck: "Content Understanding", tag: "Analyzers", front: "Domain-specific analyzers in Content Understanding", back: "<p><strong>Domain-specific analyzers</strong> (prebuilt-invoice, prebuilt-receipt, prebuilt-idDocument, prebuilt-contract, call center) are prebuilt Content Understanding analyzers tuned for specific document types, providing ready-made field schemas for common business forms.</p><p class=\"faint\">Exam trap: Content Understanding has its own domain-specific analyzers. Document Intelligence also has prebuilt models for the same document types. For standard structured forms needing top accuracy, Document Intelligence prebuilts may outperform Content Understanding generative extraction.</p>" },
  { id: "c15", deck: "Content Understanding", tag: "Custom Analyzers", front: "Custom analyzers and zero-shot extraction", back: "<p><strong>Custom analyzers</strong> in Content Understanding work <strong>zero-shot</strong> \u2014 you describe the fields you want in plain language in the field schema, and the generative model extracts them without any labeled training data.</p><p class=\"faint\">Exam trap: zero-shot means no training data is required. This is the key difference from Document Intelligence custom models, which require labeled examples to train. Labeled examples can improve accuracy but are optional in Content Understanding.</p>" },
  { id: "c16", deck: "Content Understanding", tag: "Custom Analyzers", front: "Labeled examples in Content Understanding", back: "<p><strong>Labeled examples</strong> are optional annotated samples you can provide to a Content Understanding custom analyzer to improve extraction accuracy beyond the zero-shot baseline, without requiring as many examples as traditional ML training.</p><p class=\"faint\">Exam trap: labeled examples improve accuracy but are not required. Zero-shot works out of the box. If a question asks what is unique about Content Understanding custom extraction, the answer is zero-shot; labeled examples are the <em>accuracy improvement</em> option.</p>" },
  { id: "c17", deck: "Content Understanding", tag: "Output", front: "Confidence scores in Content Understanding", back: "<p>Content Understanding returns an optional <strong>confidence score</strong> (0 to 1) for each extracted field value, indicating how confident the model is in the extraction, helping downstream systems flag low-confidence results for human review.</p><p class=\"faint\">Exam trap: confidence scores are returned per field, not per document. A document may have some high-confidence fields and some low-confidence ones. Build human review triggers based on per-field thresholds.</p>" },
  { id: "c18", deck: "Content Understanding", tag: "Output", front: "Grounding and source references in Content Understanding", back: "<p>Content Understanding returns <strong>grounding data</strong> (bounding boxes for documents and images, timestamps for audio and video) alongside extracted values, showing exactly where in the source content each field value came from.</p><p class=\"faint\">Exam trap: grounding in Content Understanding output is about source provenance, not AI safety grounding. It lets downstream apps display evidence, build citation links, or verify extraction accuracy against the source.</p>" },
  { id: "c19", deck: "Content Understanding", tag: "Output", front: "Markdown output for RAG pipelines", back: "<p>Content Understanding can output <strong>Markdown-formatted text</strong>, preserving document structure (headings, tables, lists) in a way that is compatible with RAG pipeline chunking and indexed retrieval in Azure AI Search.</p><p class=\"faint\">Exam trap: Markdown output is produced by the RAG analyzers (prebuilt-documentSearch, etc.). Base analyzers return structured JSON. Choose your analyzer based on whether you need search-ready chunks (RAG analyzer) or typed field extraction (base or custom analyzer).</p>" },
  { id: "c20", deck: "Content Understanding", tag: "Comparison", front: "Content Understanding vs Document Intelligence", back: "<p><strong>Content Understanding</strong> is generative and multimodal (documents, images, audio, video), supports zero-shot extraction, and handles unstructured content. <strong>Document Intelligence</strong> is purpose-trained, deterministic, documents-only, and the only option with a container for offline/air-gapped use.</p><p class=\"faint\">Exam trap: for standard structured forms (invoice, receipt, ID, mortgage) with a known schema needing top accuracy and low latency, Document Intelligence prebuilt models typically win. For unstructured, multimodal, or zero-shot scenarios, Content Understanding wins.</p>" },
  { id: "c21", deck: "Content Understanding", tag: "Comparison", front: "Azure Document Intelligence containers", back: "<p><strong>Azure Document Intelligence in Foundry Tools</strong> is the only Foundry Tools service that offers a container deployment option, enabling offline or air-gapped document processing without internet connectivity.</p><p class=\"faint\">Exam trap: Content Understanding has no container option. If a question requires on-premises or air-gapped document extraction, the answer is Document Intelligence containers, not Content Understanding.</p>" },
  { id: "c22", deck: "Content Understanding", tag: "Comparison", front: "Azure AI Video Indexer vs Content Understanding for video", back: "<p><strong>Azure AI Video Indexer</strong> is a separate active service providing prebuilt video insights (faces, labels, transcripts, OCR, topics). <strong>Content Understanding</strong> is preferred when you need schema-driven field extraction from video via a configurable analyzer.</p><p class=\"faint\">Exam trap: both services process video. Video Indexer returns a fixed set of prebuilt insights; Content Understanding returns fields you define. If the scenario says \u201ccustom fields from video,\u201d Content Understanding is the answer; if it says \u201cfacial recognition in video,\u201d Video Indexer may be appropriate.</p>" }
];
